    "open_page": ["browser.navigate"],
    "click_button": ["browser.interact"],
    "fill_and_submit": ["browser.interact", "browser.submit"],
    "resize_viewport": ["browser.viewport"],
    "get_computed_style": ["browser.read"],
    "record_result": ["memory.write"],
}

