def _banner(title: str) -> None:
    print("\n" + "â•" * 60)
    print(f"  {title}")
    print("â•" * 60 + "\n")


def _section(title: str) -> None:
    print(f"\nâ”€â”€ {title} " + "â”€" * max(0, 50 - len(title)))


if __name__ == "__main__":
    html_path = str(Path(__file__).parent / "sample" / "index.html")
    asyncio.run(run(html_path))

